// src/app/use-cases/auth/sign-in.ts
class SignIn {
  authRepository;
  sessionRepository;
  tokenRepository;
  passwordHash;
  tokenManager;
  constructor(authRepository, sessionRepository, tokenRepository, passwordHash, tokenManager) {
    this.authRepository = authRepository;
    this.sessionRepository = sessionRepository;
    this.tokenRepository = tokenRepository;
    this.passwordHash = passwordHash;
    this.tokenManager = tokenManager;
  }
  async execute(c3, user, userAgent) {
    const existingUser = await this.authRepository.getUserWithSettingAndProfileByEmail(user.email);
    if (!existingUser) {
      throw new invariant_error_default(ERROR.EMAIL_NOT_REGISTERED);
    }
    const isPasswordValid = await this.passwordHash.comparePassword(user.password, existingUser.password);
    if (!isPasswordValid) {
      throw new invariant_error_default(ERROR.INVALID_CREDENTIALS);
    }
    if (!existingUser.isVerified) {
      return "unverified";
    }
    const setting = existingUser.setting;
    if (setting?.enable2FA) {
      const token2 = await this.tokenManager.generateVerificationToken(user.email, existingUser.username);
      const verificationToken = new VerificationTokenEntity(user.email, token2, this.tokenManager.getTokenExpired());
      await this.tokenRepository.createOrUpdateVerificationToken(verificationToken);
      return "2fa";
    }
    const deviceId = CookieHelper.getDeviceId(c3) ?? CookieHelper.generateDeviceId();
    const sessionTokenEntity = new SessionTokenEntity(existingUser.id, existingUser.username, deviceId, user.email, userAgent, !!existingUser.profile);
    const token = await this.tokenManager.generateSessionToken(sessionTokenEntity);
    const sessionEntity = new SessionEntity(existingUser.id, token, deviceId, userAgent, user.email, this.tokenManager.getTokenExpired());
    const session = await this.sessionRepository.createOrUpdateSession(sessionEntity, `Login from ${userAgent}`);
    CookieHelper.setAuthCookies(c3, session);
    return "success";
  }
}
