// src/app/use-cases/channels/unsubscribe-channel.ts
class UnsubscribeChannel {
  channelRepository;
  channelSubscriberRepository;
  constructor(channelRepository, channelSubscriberRepository) {
    this.channelRepository = channelRepository;
    this.channelSubscriberRepository = channelSubscriberRepository;
  }
  async execute(session, channelId) {
    const channel = await this.channelRepository.getGeneralChannelById(channelId, session.userId);
    if (!channel) {
      throw new not_found_error_default(ERROR.CHANNEL_NOT_FOUND);
    }
    if (!channel.isSubscriber) {
      throw new invariant_error_default(ERROR.USER_IS_NOT_SUBSCRIBER);
    }
    if (channel.totalSubscribers === 1) {
      await this.channelRepository.softDeleteChannel(channelId);
      return;
    }
    const totalAdmins = await this.channelSubscriberRepository.getTotalAdmins(channelId);
    const isOnlyOneAdmin = channel.isAdmin && totalAdmins === 1;
    if (isOnlyOneAdmin) {
      const subscribers = await this.channelSubscriberRepository.getSubscribers(channelId, {
        limit: 2
      });
      const otherSubscriber = subscribers.data.find((member) => member.id !== session.userId);
      if (otherSubscriber) {
        await this.channelSubscriberRepository.addAdmin(channelId, otherSubscriber.id);
      }
    }
    await this.channelSubscriberRepository.unsubscribeChannel(channelId, session.userId);
  }
}
