class UpdateChannel {
  channelRepository;
  storageRepository;
  constructor(channelRepository, storageRepository) {
    this.channelRepository = channelRepository;
    this.storageRepository = storageRepository;
  }
  async execute(session, data, imageFile) {
    const currentChannel = await this.channelRepository.getPublicOrJoinedChannelById(data.id, session.userId);
    if (!currentChannel) {
      throw new not_found_error_default(ERROR.CHANNEL_NOT_FOUND);
    }
    if (!currentChannel.isAdmin) {
      throw new authorization_error_default(ERROR.UNAUTHORIZE);
    }
    if (data.name && data.name !== currentChannel.name) {
      const isNameAvailable = await this.channelRepository.checkChannelNameAvailability(session.userId, data.name);
      if (!isNameAvailable) {
        throw new invariant_error_default(ERROR.CHANNEL_NAME_DUPLICATED);
      }
    }
    let fileId;
    if (imageFile) {
      const file = await this.storageRepository.uploadFile(imageFile);
      fileId = file.id;
      data.imageUrl = file.url;
    }
    try {
      const result = await this.channelRepository.updateChannel(session.userId, data);
      if (fileId && currentChannel.imageUrl) {
        await this.storageRepository.deleteFileByUrl(currentChannel.imageUrl);
      }
      return result;
    } catch (e2) {
      if (fileId) {
        await this.storageRepository.deleteFile(fileId);
      }
      throw e2;
    }
  }
}
