class CreateGroup {
  groupRepository;
  profileRepository;
  blockedUserRepository;
  storageRepository;
  constructor(groupRepository, profileRepository, blockedUserRepository, storageRepository) {
    this.groupRepository = groupRepository;
    this.profileRepository = profileRepository;
    this.blockedUserRepository = blockedUserRepository;
    this.storageRepository = storageRepository;
  }
  async validateGroupMember(userId, memberIds) {
    const validProfiles = await this.profileRepository.findProfileUserIdsByUserIdsExceptUserId(memberIds, userId);
    if (validProfiles.length < memberIds.length) {
      const validUserIds = validProfiles.map((v3) => v3.userId);
      const notValidUserId = memberIds.find((id) => !validUserIds.includes(id));
      throw new invariant_error_default(ERROR.MEMBER_ID_NOT_FOUND, [
        "members",
        notValidUserId
      ]);
    }
    const blockedUsers = await this.blockedUserRepository.getBlockedUserIdsByUserIds(userId, memberIds);
    if (blockedUsers.length > 0) {
      const blockedUserIds = blockedUsers.map((v3) => v3.blockedUserId);
      const blockedUserId = memberIds.find((id) => blockedUserIds.includes(id));
      throw new invariant_error_default(ERROR.ADD_BLOCKED_USERS_NOT_ALLOWED, [
        "members",
        blockedUserId
      ]);
    }
    const blockedByUsers = await this.blockedUserRepository.getBlockedByUserIdsByUserIds(userId, memberIds);
    if (blockedByUsers.length > 0) {
      const blockedByUserIds = blockedUsers.map((v3) => v3.blockedUserId);
      const blockedByUserId = memberIds.find((id) => blockedByUserIds.includes(id));
      throw new invariant_error_default(ERROR.ADDDED_BY_BLOCKED_USER_NOT_ALLOWED, [
        "members",
        blockedByUserId
      ]);
    }
    return;
  }
  async execute(session, data, imageFile) {
    const isNameAvailable = await this.groupRepository.checkGroupNameAvailability(session.userId, data.name);
    if (!isNameAvailable) {
      throw new invariant_error_default(ERROR.GROUP_NAME_DUPLICATED);
    }
    await this.validateGroupMember(session.userId, data.memberIds);
    let fileId;
    if (imageFile) {
      const file = await this.storageRepository.uploadFile(imageFile);
      fileId = file.id;
      data.imageUrl = file.url;
    }
    try {
      const result = await this.groupRepository.createGroup(data);
      return result;
    } catch (e2) {
      if (fileId) {
        await this.storageRepository.deleteFile(fileId);
      }
      throw e2;
    }
  }
}
