// src/domains/rooms/entities/room-entity.ts
class RoomEntity {
  id;
  type;
  ownerId;
  pinned;
  archived;
  totalUnreadMessage;
  user1;
  user2;
  group;
  channel;
  lastMessage;
  constructor(id, type, ownerId, pinned, archived, totalUnreadMessage, user1, user2, group, channel, lastMessage) {
    this.id = id;
    this.type = type;
    this.ownerId = ownerId;
    this.pinned = pinned;
    this.archived = archived;
    this.totalUnreadMessage = totalUnreadMessage;
    this.user1 = user1;
    this.user2 = user2;
    this.group = group;
    this.channel = channel;
    this.lastMessage = lastMessage;
  }
  toDTO() {
    let name = "";
    let imageUrl = null;
    let isActive = false;
    let actionId = "";
    if (this.type === "PRIVATE") {
      const user = this.user1?.id === this.ownerId ? this.user2 : this.user1;
      imageUrl = user?.imageUrl ?? "";
      actionId = user?.id ?? "";
      if (this.user1?.id === this.user2?.id) {
        name = "Saved Messages";
      } else {
        name = user?.name ?? "Unknown";
      }
    } else if (this.type === "GROUP" && this.group) {
      name = this.group.name;
      imageUrl = this.group?.imageUrl ?? null;
      isActive = this.group.isActive;
      actionId = this.group.id;
    } else if (this.type === "CHANNEL" && this.channel) {
      name = this.channel.name;
      imageUrl = this.channel?.imageUrl ?? null;
      isActive = this.channel.isActive;
      actionId = this.channel.id;
    }
    return {
      id: this.id,
      actionId,
      type: ROOM_TYPE_TO_DTO[this.type],
      name,
      imageUrl,
      pinned: this.pinned,
      archived: this.archived,
      isActive,
      totalUnreadMessages: this.totalUnreadMessage,
      lastMessage: this.lastMessage?.toDTO() ?? null
    };
  }
}

