class SettingEntity {
  id;
  userId;
  timeFormat;
  language;
  notifications;
  enable2FA;
  showLastSeen;
  allowAddToGroup;
  constructor(id, userId, timeFormat, language, notifications, enable2FA, showLastSeen, allowAddToGroup) {
    this.id = id;
    this.userId = userId;
    this.timeFormat = timeFormat;
    this.language = language;
    this.notifications = notifications;
    this.enable2FA = enable2FA;
    this.showLastSeen = showLastSeen;
    this.allowAddToGroup = allowAddToGroup;
  }
  toDTO() {
    return {
      id: this.id,
      userId: this.userId,
      timeFormat: this.timeFormat,
      language: this.language,
      notifications: this.notifications,
      enable2FA: this.enable2FA,
      showLastSeen: this.showLastSeen,
      allowAddToGroup: this.allowAddToGroup
    };
  }
}

// src/infrastuctures/repositories/setting/setting-repository-impl.ts
class SettingRepositoryImpl {
  async updateSetting(setting) {
    const result = await prisma.setting.upsert({
      where: { userId: setting.userId },
      create: {
        userId: setting.userId,
        language: setting.language,
        timeFormat: setting.timeFormat ? PrismaHelper.convertTimeFormat(setting.timeFormat) : undefined,
        notifications: setting.notifications,
        allowAddToGroup: setting.allowAddToGroup,
        enable2FA: setting.enable2FA,
        showLastSeen: setting.showLastSeen
      },
      update: {
        language: setting.language,
        timeFormat: setting.timeFormat ? PrismaHelper.convertTimeFormat(setting.timeFormat) : undefined,
        notifications: setting.notifications,
        allowAddToGroup: setting.allowAddToGroup,
        enable2FA: setting.enable2FA,
        showLastSeen: setting.showLastSeen
      }
    });
    return new SettingEntity(result.id, result.userId, PrismaHelper.convertDBTimeFormat(result.timeFormat), PrismaHelper.convertDBLanguage(result.language), result.notifications.map(PrismaHelper.convertDBNotification), result.enable2FA, result.showLastSeen, result.allowAddToGroup);
  }
  async getSettingByUserId(userId) {
    const result = await prisma.setting.findUnique({
      where: { userId }
    });
    if (!result)
      return null;
    return new SettingEntity(result.id, result.userId, PrismaHelper.convertDBTimeFormat(result.timeFormat), PrismaHelper.convertDBLanguage(result.language), result.notifications.map(PrismaHelper.convertDBNotification), result.enable2FA, result.showLastSeen, result.allowAddToGroup);
  }
}

