// src/app/use-cases/groups/delete-group.ts
class DeleteGroup {
  groupRepository;
  constructor(groupRepository) {
    this.groupRepository = groupRepository;
  }
  async execute(session, groupId) {
    const currentGroup = await this.groupRepository.getPublicOrJoinedGroupById(groupId, session.userId);
    if (!currentGroup) {
      throw new not_found_error_default(ERROR.GROUP_NOT_FOUND);
    }
    if (!currentGroup.isAdmin) {
      throw new authorization_error_default(ERROR.UNAUTHORIZE);
    }
    await this.groupRepository.softDeleteGroup(groupId);
  }
}
DeleteGroup = __legacyDecorateClassTS([
  Kt(),
  __legacyDecorateParamTS(0, Yt(KEYS.GroupRepository)),
  __legacyMetadataTS("design:paramtypes", [
    typeof GroupRepository === "undefined" ? Object : GroupRepository
  ])
], DeleteGroup);

