// src/app.ts
var app = new Hono2().basePath("/api");
app.use(logger(customLogger));
app.use("/*", cors({
  origin: process.env.APP_URL,
  allowMethods: ["GET", "POST", "PUT", "DELETE", "OPTIONS", "PATCH"],
  maxAge: 600,
  credentials: true
}));
var { injectWebSocket, upgradeWebSocket } = createNodeWebSocket({ app });
createRouter(app);
app.onError((error, c3) => {
  if (error instanceof client_error_default) {
    customLogger("ERROR:", `Message: ${error.message}`, `code: ${error.statusCode}`);
    if (error instanceof invariant_error_default) {
      return c3.json(createError(error.message, error.path), error.statusCode);
    }
    return c3.json(createError(error.message), error.statusCode);
  }
  if (error instanceof import_library.PrismaClientKnownRequestError) {
    console.log(createError(error.message));
    return c3.json(createError(ERROR.INTERNAL_SERVER_ERROR), 500);
  }
  console.log(error);
  customLogger("ERROR:", `Message: ${error.message}`);
  return c3.json(createError(ERROR.INTERNAL_SERVER_ERROR), 500);
});
app.get("ws/messages", sessionMiddleware, upgradeWebSocket((c3) => {
  const session = c3.get("userSession");
  return {
    onOpen(_3, ws) {
      if (!session) {
        ws.close(1008, "Unauthorized");
        return;
      }
      const websocket = container.get(KEYS.WebSocketManager);
      const rawWs = ws.raw;
      websocket.saveConnection(rawWs, session.userId);
      const onlineUserIds = websocket.getConnectionIds();
      websocket.broadcastByConnectionKeys(JSON.stringify({ type: "ONLINE", data: onlineUserIds }), onlineUserIds);
    },
    onClose: () => {
      const websocket = container.get(KEYS.WebSocketManager);
      websocket.removeConnection(session.userId);
      const onlineUserIds = websocket.getConnectionIds();
      websocket.broadcastByConnectionKeys(JSON.stringify({ type: "ONLINE", data: onlineUserIds }), onlineUserIds);
    }
  };
})).get("ws/online");
var server = serve({
  fetch: app.fetch,
  port: 8000
});
injectWebSocket(server);
var app_default = server;
